import{_ as e,c as a,o as r,aS as o}from"./chunks/framework.BItddkxz.js";const d=JSON.parse('{"title":"Figma 插件","description":"","frontmatter":{},"headers":[],"relativePath":"design/figma/plugins/index.md","filePath":"design/figma/plugins/index.md","lastUpdated":1772792710000}'),t={name:"design/figma/plugins/index.md"},i=o('<h1 id="figma-插件" tabindex="-1">Figma 插件 <a class="header-anchor" href="#figma-插件" aria-label="Permalink to &quot;Figma 插件&quot;">​</a></h1><p>Figma 插件用于扩展设计流程，例如图标库、自动排版、切图导出、标注、与开发/文档工具联动等，可从 Figma 内直接安装与运行。</p><h2 id="使用" tabindex="-1">使用 <a class="header-anchor" href="#使用" aria-label="Permalink to &quot;使用&quot;">​</a></h2><ol><li><strong>查找插件</strong>：在 Figma 中菜单栏选择「资源」→「插件」→「浏览社区中的插件」，或使用搜索框输入关键词（如 Icon、Export、Developer 等）。</li><li><strong>安装</strong>：在插件详情页点击「安装」或「Try it out」，安装后会在「资源」→「插件」→「已安装」中列出。</li><li><strong>运行</strong>：打开任意文件，在画布空白处右键选择「插件」→ 选择已安装的插件；或通过菜单「资源」→「插件」→ 选择插件运行。部分插件会要求先选中图层再运行。</li></ol><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><ul><li><a href="https://www.figma.com/plugin-docs/" target="_blank" rel="noreferrer">Figma 插件开发文档</a></li><li><a href="https://www.figma.com/community/plugins" target="_blank" rel="noreferrer">Figma 社区 - 插件</a> — 浏览与安装社区插件</li><li><a href="https://www.figma.com/plugin-docs/api/api-overview/" target="_blank" rel="noreferrer">Figma Plugin API</a> — 开发自定义插件</li></ul><hr><h2 id="autoflow" tabindex="-1">Autoflow <a class="header-anchor" href="#autoflow" aria-label="Permalink to &quot;Autoflow&quot;">​</a></h2><p><a href="https://www.figma.com/community/plugin/733902567457995893/Autoflow" target="_blank" rel="noreferrer">Autoflow</a> 用于在画布上的框架（Frame）之间自动绘制连接线，适合做界面流程图、页面跳转示意，线条会随框架移动而自动更新，无需手动画线或反复调整路径。</p><h3 id="使用步骤" tabindex="-1">使用步骤 <a class="header-anchor" href="#使用步骤" aria-label="Permalink to &quot;使用步骤&quot;">​</a></h3><ol><li>在 Figma 中打开「资源」→「插件」→ 运行 <strong>Autoflow</strong>，打开插件面板。</li><li>在面板中设置连接线的颜色、粗细，以及起点/终点的箭头等样式。</li><li>先选中<strong>起始框架</strong>，再按住 <strong>Shift</strong> 点选<strong>目标框架</strong>，插件会自动在两者之间画出一条连接线。</li><li>重复「选起始 → Shift + 选目标」即可快速连接多个框架。</li></ol><h3 id="自动追踪" tabindex="-1">自动追踪 <a class="header-anchor" href="#自动追踪" aria-label="Permalink to &quot;自动追踪&quot;">​</a></h3><p>面板保持打开时，移动任意已连接的框架，连接线会自动跟随更新。若关闭面板后再移动了框架，需重新运行一次 Autoflow，线条才会更新到新位置。</p><h3 id="参考-1" tabindex="-1">参考 <a class="header-anchor" href="#参考-1" aria-label="Permalink to &quot;参考&quot;">​</a></h3><ul><li><a href="https://www.figma.com/community/plugin/733902567457995893/Autoflow" target="_blank" rel="noreferrer">Autoflow - Figma 社区</a></li></ul><hr><h2 id="remove-bg" tabindex="-1">Remove BG <a class="header-anchor" href="#remove-bg" aria-label="Permalink to &quot;Remove BG&quot;">​</a></h2><p><a href="https://www.figma.com/community/plugin/738806391534597558/remove-bg" target="_blank" rel="noreferrer">Remove BG</a> 由 <a href="https://www.remove.bg/" target="_blank" rel="noreferrer">remove.bg</a> 提供，可在 Figma 内一键去除图片背景，适合人物、产品图抠图，无需切到其他软件。</p><h3 id="使用前-设置-api-key" tabindex="-1">使用前：设置 API Key <a class="header-anchor" href="#使用前-设置-api-key" aria-label="Permalink to &quot;使用前：设置 API Key&quot;">​</a></h3><p>插件依赖 remove.bg 的接口，需先配置 API Key：</p><ol><li>在 <a href="https://www.remove.bg/" target="_blank" rel="noreferrer">remove.bg</a> 注册并登录，在控制台获取 <strong>API Key</strong>（有免费额度）。</li><li>在 Figma 中右键画布 → <strong>插件</strong> → <strong>Remove BG</strong> → <strong>Set API Key</strong>，粘贴 Key 并保存。</li></ol><p>只需设置一次，后续在同一环境中可直接使用。</p><h3 id="使用步骤-1" tabindex="-1">使用步骤 <a class="header-anchor" href="#使用步骤-1" aria-label="Permalink to &quot;使用步骤&quot;">​</a></h3><ol><li>在画布上<strong>选中</strong>要去背景的图片（图片图层）。</li><li>右键 → <strong>插件</strong> → <strong>Remove BG</strong> → <strong>Run</strong>，或通过「资源」→「插件」→ Remove BG 运行。</li><li>插件会调用 remove.bg 接口处理，完成后当前图片会变为去背结果（背景透明）。</li></ol><p><strong>快捷方式</strong>：选中图片后按 <strong>Cmd + P</strong>（Mac）或 <strong>Ctrl + P</strong>（Win），输入 “remove bg”，选择对应命令回车即可快速去背。</p><h3 id="参考-2" tabindex="-1">参考 <a class="header-anchor" href="#参考-2" aria-label="Permalink to &quot;参考&quot;">​</a></h3><ul><li><a href="https://www.figma.com/community/plugin/738806391534597558/remove-bg" target="_blank" rel="noreferrer">Remove BG - Figma 社区</a></li><li><a href="https://www.remove.bg/" target="_blank" rel="noreferrer">remove.bg 官网与 API</a> — 注册、额度与定价说明</li></ul><div class="warning custom-block"><p class="custom-block-title">其他选择</p><p>若只是偶尔给图片去背景且已有 <strong>WPS 会员</strong>，可直接用 WPS 图片的「AI 抠图」功能，无需配置 API，操作更简单。</p></div>',28),l=[i];function n(s,g,m,h,c,f){return r(),a("div",null,l)}const p=e(t,[["render",n]]);export{d as __pageData,p as default};
